function.arguments:
{"command":"bash -lc 'set -e
CRONFILE=/etc/cron.d/var-cleanup
# Update cron to redirect output to a log file
awk '1; END{ if (NR==0) exit 1 }' "$CRONFILE" >/dev/null 2>&1 || { echo "Cron file missing"; exit 1; }
sed -n '1,120p' "$CRONFILE"
# Replace the command line with logging redirection if not already present
if ! grep -q ">> /var/log/var-cleanup.log" "$CRONFILE"; then
  tmp=$(mktemp)
  awk '{
    if ($0 ~ /^0 3 \* \* 0 root \/usr\/local\/sbin\/var-cleanup\.sh(\s|$)/) {
      print "0 3 * * 0 root /usr/local/sbin/var-cleanup.sh >> /var/log/var-cleanup.log 2>&1";
    } else { print }
  }' "$CRONFILE" > "$tmp" && cat "$tmp" > "$CRONFILE" && rm -f "$tmp"
fi
chmod 644 "$CRONFILE"
echo "-- Updated cron file --"
cat "$CRONFILE"
# Create the log file if not exists
mkdir -p /var/log
: > /var/log/var-cleanup.log
ls -l /var/log/var-cleanup.log
# Run once and log
sh /usr/local/sbin/var-cleanup.sh >> /var/log/var-cleanup.log 2>&1 || true
echo "-- Last 20 log lines --" && tail -n 20 /var/log/var-cleanup.log || true'"}

